<button v-if="drawingBusy&&store.working" :aria-label="zh?'取消计算':localize('Cancel calculation')" :title="zh?'取消计算':localize('Cancel calculation')" @click="store.cancelRun"><ToolIcon name="cancel"/></button>
<button :aria-label="zh?'撤回一笔':localize('Remove last point')" :title="zh?'撤回一笔':localize('Remove last point')" :disabled="store.busy||!draftMarking.length" @click="removeLastDrawingNode"><ToolIcon name="undo"/></button>
</template>
<template v-if="curveDrawing">
