</nav><button v-if="gpuLost" @click="gpuLost=false">{{zh?'重试 GPU 纹理预览':localize('Retry GPU texture preview')}}</button><small v-if="limitedTextureFallback" class="texture-fallback-note">{{zh?'GPU 纹理暂不可用，显示简化颜色网格以保持交互；原网格与纹理仍完整保存。可重试 GPU 或在显示设置中选择完整网格。':localize('GPU textures unavailable; showing a simplified colored mesh. Original geometry and texture remain saved. Retry GPU or select full mesh.')}}</small><Teleport v-if="mode==='mapping'||mode==='cutting'&&markingTool!=='select'" :to="mode==='mapping'?'#mapping-surface-controls':'#surface-cut-draft'" defer><div class="surface-edit-controls"><div v-if="(mode==='mapping')" class="marking-coverage"><label><input v-model="highlightUnmarked" type="checkbox">{{zh?'标出未贴附面':localize('Highlight unmapped faces')}}</label><button class="coverage-help-button" :aria-expanded="coverageHelp" :aria-label="zh?'查看花纹覆盖说明':localize('Marking coverage help')" @click="coverageHelp=!coverageHelp">?</button><span>{{markedFaces.size}} / {{surface.faces.length}} {{zh?'面含花纹记录':localize('faces have marking records')}}</span><small v-if="coverageHelp">{{zh?'灰色面没有有效花纹记录，颜色未推断；请转到侧面手绘或沿原 UV 映射。此数量不表示整面已覆盖。':localize('Grey faces have no valid marking record; colors are not inferred. Draw from a side view or map original UV. Counts do not certify full coverage.')}}</small></div><div v-if="mode==='mapping'&&!drawing" class="attached-selection-space"><label class="attached-picker">{{zh?'\u9009\u62e9\u8d34\u9644\u82b1\u7eb9':localize('Select attached marking')}}<select v-model="selectedMarkingId" aria-label="Select attached marking" :disabled="store.busy||drawing"><option value="">{{zh?'\u70b9\u51fb\u6a21\u578b\u6216\u9009\u62e9\u8bb0\u5f55':localize('Click model or select a record')}}</option><option v-for="m in validMarkings" :key="m.id" :value="m.id">{{m.name}}</option></select></label><div v-if="selectedMarking" class="attached-selection" role="status" :data-marking-id="selectedMarking.id"><strong>{{selectedMarking.name}}</strong><label>{{zh?'宽 mm':localize('Width mm')}}<input v-model.number="markingWidth" aria-label="Attached marking width" type="number" min=".01" step=".1" :disabled="store.busy||selectedMarking.locked||drawing"></label><label>{{zh?'高 mm':localize('Height mm')}}<input v-model.number="markingHeight" aria-label="Attached marking height" type="number" min=".01" step=".1" :disabled="store.busy||selectedMarking.locked||drawing"></label><label>°<input v-model.number="markingAngle" aria-label="Attached marking rotation" type="number" step="1" :disabled="store.busy||selectedMarking.locked||drawing"></label><button :disabled="store.busy||selectedMarking.locked||drawing||markingWidth<=0||markingHeight<=0" @click="resizeAttached">{{freeTransform?(zh?'确认变换 Enter':localize('Confirm transform Enter')):(zh?'应用尺寸与旋转':localize('Apply size and rotation'))}}</button><button :disabled="store.busy||selectedMarking.locked" @click="beginMarkingEdit">{{zh?'编辑轮廓节点':localize('Edit contour nodes')}}</button><button :disabled="store.busy||selectedMarking.locked" :aria-pressed="freeTransform" @click="freeTransform?cancelFreeTransform():beginFreeTransform()">{{freeTransform?(zh?'取消变换 Esc':localize('Cancel transform Esc')):(zh?'自由变换 Ctrl＋T':localize('Free transform Ctrl+T'))}}</button><span>{{selectedMarking.locked?(zh?'已锁定':localize('Locked')):(freeTransform?(zh?'拖动框内移动，方柄缩放，圆柄旋转；Shift 等比／15°，Enter 确认':localize('Drag squares to resize, circle to rotate; Shift constrains, Enter confirms')):(zh?'拖动花纹移动，方柄缩放，圆柄旋转':localize('Drag marking to move, squares to resize, circle to rotate')))}}</span></div></div><div v-if="(mode==='mapping'||mode==='cutting')&&!drawing&&markingTool!=='select'" class="surface-brush-controls"><label v-if="mode==='cutting'">{{zh?'画笔操作':localize('Paint operation')}}<select v-model="markingTool" aria-label="Cutting paint operation" :disabled="store.busy"><option value="add">{{zh?'添加花纹区域':localize('Add color area')}}</option><option value="erase">{{zh?'擦除已选花纹':localize('Erase selected marking')}}</option></select></label><label v-if="mode==='cutting'&&markingTool==='erase'">{{zh?'擦除花纹':localize('Marking to erase')}}<select v-model="selectedMarkingId" aria-label="Cutting paint target" :disabled="store.busy"><option value="">{{zh?'选择未锁定的花纹':localize('Choose an unlocked marking')}}</option><option v-for="marking in validMarkings" :key="marking.id" :value="marking.id" :disabled="marking.locked">{{marking.name}}{{marking.locked?(zh?' · 已锁定':localize(' · Locked')):''}}</option></select></label><small v-if="mode==='cutting'&&markingTool==='erase'&&(!selectedMarking||selectedMarking.locked)" class="cut-paint-help" role="status">{{zh?'先选择一条未锁定的花纹，再在模型上擦除。':localize('Choose an unlocked marking before erasing on the model.')}}</small><label>{{zh?'笔刷半径 mm':localize('Brush radius mm')}}<input v-model.number="brushRadius" aria-label="Surface brush radius" type="number" min=".1" max="200" step=".5" :disabled="store.busy"></label><label>{{zh?'笔刷形状':localize('Brush shape')}}<select v-model="brushShape" aria-label="Surface brush shape" :disabled="store.busy"><option value="round">{{zh?'圆形':localize('Round')}}</option><option value="square">{{zh?'方形':localize('Square')}}</option></select></label><label v-if="markingTool==='add'"><input v-model="brushSymmetric" aria-label="Symmetric surface paint" type="checkbox" :disabled="store.busy">{{zh?'对称绘制半边':localize('Paint one half symmetrically')}}</label><label v-if="markingTool==='add'">{{zh?'颜色':localize('Color')}}<input v-model="markingColor" aria-label="Surface brush color" type="color" :disabled="store.busy"></label><span>{{zh?'在模型上拖动涂绘；松开保存一笔。':localize('Drag on the model; release to save one stroke.')}}</span></div><div v-if="(mode==='mapping')" class="surface-drawing"><template v-if="drawing"><select v-model="drawingMode" :disabled="store.busy||!!draftHoles.length||!!draftCurves.length" aria-label="Surface drawing mode"><option value="freehand">{{zh?'自由手绘':localize('Freehand')}}</option><option value="polygon">{{zh?'折线':localize('Polygon')}}</option><option value="spline">{{zh?'闭合样条':localize('Closed spline')}}</option></select><label v-if="drawingMode==='spline'">{{zh?'张力':localize('Tension')}}<input v-model.number="splineTension" aria-label="Surface spline tension" type="range" min="0" max="1" step=".05"></label><input v-model="markingName" :disabled="store.busy||!!editingMarkingId" maxlength="120" :aria-label="zh?'花纹名称':localize('Marking name')"><input v-model="markingColor" :disabled="store.busy||!!editingMarkingId" type="color" :aria-label="zh?'花纹颜色':localize('Marking color')"><small v-if="splineError">{{drawingError}}</small><button v-if="editingMarkingId" :disabled="selectedDrawingHandle<0||store.busy" @click="deleteDrawingNode">{{zh?'删除选中节点':localize('Delete selected node')}}</button><span>{{draftMarking.length}} {{zh?'点':localize('points')}}</span><button :disabled="store.busy||draftMarking.length<3||!!splineError||!markingName.trim()" @click="saveDrawing">{{editingMarkingId?(zh?'确认花纹编辑':localize('Confirm marking edit')):(zh?'闭合并贴附':localize('Close and attach'))}}</button></template></div></div></Teleport><Teleport v-if="mode==='cutting'" to="#surface-cut-draft" defer><div v-if="curveDrawing" class="curve-cut-draft"><label>{{zh?'裁剪线名称':localize('Cut line name')}}<input v-model="curveName" maxlength="120"></label><label><input v-model="curveSymmetric" type="checkbox">{{zh?'对称绘制':localize('Symmetric')}}</label><label class="check-label"><input v-model="curveClosed" type="checkbox" :disabled="store.busy" :aria-label="zh?'闭合裁线':localize('Closed cut path')">{{zh?'闭合裁线':localize('Closed cut path')}}</label><p role="status">{{curveClosed?(zh?'闭合裁线至少需要三个不同节点；关闭此项可绘制开放结构缝或省道。':localize('A closed cut needs at least three distinct nodes. Uncheck to draw an open seam or dart.')):(zh?'开放结构缝或省道至少需要两个不同节点；路径不能分叉或重走。':localize('An open seam or dart needs at least two distinct nodes. Branching or retraced paths cannot be saved.'))}}</p><label v-if="!curveSurfaceAnchored">{{zh?'张力':localize('Tension')}}<input v-model.number="curveTension" type="range" min="0" max="1" step=".05"></label><label class="check-label cut-node-visibility"><input v-model="showCurveNodes" type="checkbox" @change="!showCurveNodes&&(selectedCurveNode=-1)">{{zh?'编辑控制节点':localize('Edit control nodes')}}</label><div class="curve-node-actions"><span role="status">{{selectedCurveNode>=0?(zh?'选中节点 ':localize('Selected node '))+(selectedCurveNode+1):(zh?'点击圆点选中，拖动调整':localize('Select a visible node and drag to adjust'))}}</span><button :disabled="store.busy||!showCurveNodes||selectedCurveNode<0||curvePoints.length>=400||(!curveClosed&&selectedCurveNode===curvePoints.length-1)" @click="insertCurveNode()">{{zh?'选中点后插入':localize('Insert after selected')}}</button><button :disabled="store.busy||!showCurveNodes||selectedCurveNode<0||curvePoints.length<=(curveClosed?3:2)" @click="deleteCurveNode">{{zh?'删除选中节点':localize('Delete selected node')}}</button><button :aria-pressed="curveAdding" :disabled="store.busy" @click="curveAdding=!curveAdding">{{curveAdding?(zh?'正在追加路径点':localize('Adding path points')):(zh?'追加路径点':localize('Add path points'))}}</button><button :disabled="store.busy" @click="cancelCurve">{{zh?'取消路径修改':localize('Cancel path edits')}}</button></div><span>{{curvePoints.length}} {{zh?'点':localize('points')}}</span><button :disabled="store.busy||curvePoints.length<(curveClosed?3:2)||!curveRegions.length||!!curvePreview.error||!curveName.trim()" @click="saveCurve">{{zh?'保存裁剪线':localize('Save cut line')}}</button><small>{{curvePreview.error||(zh?'点击并拖动圆点；Ctrl 点击路径插入，Delete 删除。修改暂存，保存后更新真实曲面切缝；Esc 取消。':localize('Select and drag knots; Ctrl-click the path to insert, Delete to remove. Confirm to update real mesh cuts; Escape cancels.'))}}</small></div></Teleport><p v-if="dropMessage" class="drop-message" role="status">{{dropMessage}}</p><small v-if="drawing" class="drawing-help">{{editingMarkingId?(zh?'拖动外轮廓或孔洞节点；Ctrl 点击插入，Delete 删除。Shift 拖动移动整个花纹，确认后保存。源节点可超出曲面，模型显示裁剪后的边界。':localize('Drag contou